CREATE TABLE restore_users (
  id UUID PRIMARY KEY,
  wallet_address VARCHAR(56) NOT NULL UNIQUE,
  created_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE restore_flights (
  id UUID PRIMARY KEY,
  flight_number VARCHAR(32) NOT NULL,
  from_airport VARCHAR(16) NOT NULL,
  to_airport VARCHAR(16) NOT NULL,
  departure_time TIMESTAMPTZ NOT NULL,
  price_cents INTEGER NOT NULL CHECK (price_cents >= 0)
);

CREATE TABLE restore_bookings (
  id UUID PRIMARY KEY,
  booking_reference VARCHAR(32) NOT NULL UNIQUE,
  user_id UUID NOT NULL REFERENCES restore_users(id),
  flight_id UUID NOT NULL REFERENCES restore_flights(id),
  status VARCHAR(32) NOT NULL,
  amount_cents INTEGER NOT NULL CHECK (amount_cents >= 0),
  created_at TIMESTAMPTZ NOT NULL
);

